pub struct PatternValueNode(pub P<ParseNode>);

impl PatternValueNode {
    pub fn cast(node: P<ParseNode>) -> Option<Self> {
        match node.d {
            ParseNodeDetails::PatternValue(_) => Some(Self(node)),
            _ => None,
        }
    }

    pub fn d(self) -> &'static PatternValueNodeDetails {
        match &self.0.get().d {
            ParseNodeDetails::PatternValue(d) => d,
            _ => unreachable!("PatternValueNode holds another variant"),
        }
    }
}

impl Deref for PatternValueNode {
    type Target = ParseNode;

    fn deref(&self) -> &ParseNode {
        self.0.get()
    }
}

